import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    v = []
    for _ in range(n):
        v.append(int(next(iterator)))

    # Create a sorted copy of the array
    sorted_v = sorted(v)

    # Find the first index where the original array differs from the sorted array
    start = -1
    for i in range(n):
        if v[i] != sorted_v[i]:
            start = i
            break

    if start == -1:
        # Already sorted
        print("1 1")
        return

    # Find the last index where the original array differs from the sorted array
    end = -1
    for i in range(n - 1, -1, -1):
        if v[i] != sorted_v[i]:
            end = i
            break

    # Check if reversing the subarray from start to end (0-based) makes the array sorted
    # The reversed subarray should match the corresponding part of the sorted array
    # Specifically, v[start : end+1] reversed must equal sorted_v[start : end+1]

    subarray = v[start : end + 1]
    reversed_subarray = subarray[::-1]

    if reversed_subarray == sorted_v[start : end + 1]:
        # Valid solution found. Output 1-based indices.
        print(f"{start + 1} {end + 1}")
    else:
        print("impossible")

if __name__ == "__main__":
    solve()
